INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bb55db15-57da-46f0-bb9f-f8ae171b0372', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 5, 'A nova identidade', NULL, '{"intro": "A cura redefine sua narrativa pessoal.", "prayer": "Afirme essas qualidades em voz alta.", "practice": "Defina-se agora com tr\u00eas qualidades que n\u00e3o dependem da sua dor.", "reflection": "Voc\u00ea n\u00e3o \u00e9 o que te aconteceu, voc\u00ea \u00e9 o que voc\u00ea escolhe fazer com isso.", "journal_prompt": "Como \u00e9 a sua vida quando voc\u00ea aceita quem voc\u00ea realmente \u00e9?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;